// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property() public {
        // The rule: after Ownable construction, owner() must not return address(0).
        // The reference C returns the deployer (non-zero). The mutant returns address(0),
        // so the assertion fails for every execution of the mutant.
        assertTrue(c.owner() != address(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address originalOwner) public {
        vm.assume(originalOwner != address(0));
        C testC = new C(address(this), originalOwner);
        address returnedOwner = testC.owner();
        assertTrue(returnedOwner == originalOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address deployer) public {
        vm.assume(deployer != address(0));
        c = new C(deployer, address(this));
        assertTrue(c.owner() == deployer);
    }
}
